        int length = scanner.nextInt();
        String text = scanner.next();
        scanner.close();

        int maxOutside = 0, maxInside = 0, currentCount = 0;
        int insideCount = 0;
        boolean insideParentheses = false;

        for (int i = 0; i < length; i++) {
            char ch = text.charAt(i);
